window.FILM_WORK_PROMPTS={"work_id":"src-511fd3a9e5b4cd1b","records":[{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-b2a806d8c2556b6d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (45).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"茂密丛林中，前景横卧着大量身穿土色衣物的人物，中景站立着数匹白马与棕马，背景深处聚集着密集的人影，右侧竖立着一根粗壮的树干。","analysis":"画面采用纵深构图，前景人物横卧于地面，仅可见背部与头部轮廓，中景马匹体型较大，背景人影因距离显得极小。右侧树干垂直贯穿画面，形成视觉分割。光线为柔和的散射光，整体色调以深绿与土黄为主，远景笼罩在灰白色的雾气中，明暗对比平缓。","prompt":"这是一张低分辨率的丛林场景画面。前景地面上横卧着许多身穿土黄色与红褐色衣物的人物，他们背对镜头或侧卧，身体轮廓模糊。中景处站立着几匹马，包括左侧的白马和中间的棕马，马匹后方是密集站立的人群。画面右侧有一根粗壮的浅色树干垂直向上延伸，周围环绕着茂密的深绿色树叶。背景深处是灰白色的雾气，隐约可见更多的人影。整体光线柔和，色彩以自然的绿色和土色为主，呈现出一种压抑且拥挤的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:54:36-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (45).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.476,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-1f195d696f068f68","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-8363215a9ff7581f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/19 (45).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"丛林背景中，左侧站立一名身穿深色铠甲的长发男子，右侧一名头戴红巾的男子双手持竹制管乐器置于嘴边，两人并排处于茂密植被前。","analysis":"画面采用平视视角，两名人物占据前景主要位置，背景为虚化的绿色丛林。左侧人物可见上半身，身着深色金属质感护甲，肩带斜跨；右侧人物可见上半身，身着红褐色条纹衣物，头部包裹红色头巾。光线为自然散射光，人物面部及衣物受光均匀，背景树叶呈现深浅不一的绿色层次，整体色调偏暖。","prompt":"低分辨率画面，丛林环境，背景是模糊的绿色树叶和树干。前景左侧站立一名长发男子，身穿深褐色金属铠甲，肩部有皮带扣，神情严肃。前景右侧一名男子，头戴红色花纹头巾，身穿红褐色条纹宽袖衣物，双手持握一束竖直的竹管乐器置于嘴前。两人并排，占据画面下半部分，光线柔和，色彩以绿色背景和人物身上的红褐色调为主。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:54:43-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/19 (45).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.492,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-a90708d63dd40b38","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-4eb42f7e5307c2ad","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/31 (44).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"画面中央是一具干枯的类人形物体，头部和上半身可见，头顶上方有一根深色垂直柱状物。背景是模糊的绿色树林和植被，整体环境显得阴暗潮湿。","analysis":"构图采用中心对称，主体位于画面正中，占据约三分之二的垂直空间。可见范围包括头部、颈部和肩部，身体呈直立或悬挂姿态。镜头视角平视，光线为自然散射光，整体色调偏暗，以土褐色和灰绿色为主。主体表面质感粗糙，与背景虚化的绿色植被形成明暗和色彩对比。","prompt":"低分辨率画面，中心构图。画面正中是一个干枯的类人形物体，头部和上半身清晰可见，皮肤呈土褐色，表面极度干瘪，头顶有黑色毛发，头顶正上方有一根深色垂直柱状物穿过。背景是虚化的绿色树林，光线昏暗，色彩饱和度低。主体质感粗糙，与背景的绿色形成对比，整体氛围阴森。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:54:50-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/31 (44).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.502,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-1299543250bc614a","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-e69e7dfc591ad08f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/43 (44).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"一名深色头发的女子位于画面中央，身着土黄色宽领上衣，神情平静。背景为模糊的树林与土坡，远处有模糊人影。","analysis":"画面采用中心构图，主体人物占据前景主要位置，仅可见头部及肩颈上半身。背景环境占比约三分之一，呈现明显的景深虚化效果。光线为柔和的自然散射光，人物面部受光均匀，无明显阴影。色彩以土黄、褐色与背景的灰绿为主，整体色调偏暖且饱和度较低。","prompt":"低分辨率画面，一名深色头发的女子位于画面正中央，头发向后束起，身穿土黄色宽领上衣，领口边缘有浅色装饰，露出肩颈线条。人物面部表情平静，眼神直视前方。背景为虚化的户外环境，可见模糊的树木枝干与土黄色地面，远处有模糊的人影轮廓。光线柔和自然，无强烈阴影，整体色调偏暖，以土黄、褐色与灰绿色为主，画面质感略显粗糙。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:54:57-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/43 (44).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.5,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-353232ffe5e6b72a","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-4ea23a289999e277","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/55 (40).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"一名戴头盔的长发男子与一名女子并排坐于装饰华丽的深色车厢内，男子位于左侧，女子位于右侧，背景可见绿色植被。","analysis":"画面主体为车厢内的两名人物，仅上半身可见。男子位于画面左侧，头戴金属头盔，身穿深色护甲与紫红色衣物，身体微侧。女子位于右侧，长发披肩，身穿浅色上衣。两人背后是带有金色卷草纹饰的深蓝色车厢内壁。画面左侧边缘可见绿色树叶，光线自然，色彩层次分明，人物面部受光均匀。","prompt":"这是一张低分辨率的影视静帧。画面中心是两名并排坐于车厢内的人物。左侧男子头戴银色金属头盔，露出金色长发，身穿深色皮革护甲，内衬紫红色衣物，面部朝向左上方。右侧女子长发披肩，身穿白色上衣，头部微仰。两人身后是深蓝色的车厢内壁，装饰有醒目的金色卷草纹样。画面左侧边缘可见模糊的绿色树叶背景。光线柔和自然，人物面部受光均匀，色彩以深蓝、金色、紫红和绿色为主，呈现出一种古朴的质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T10:55:09-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/55 (40).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.504,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-7312bb700f690d7d","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-eff0cdb2e362386e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/06 (45).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"一名身穿深蓝色长裙与白色领饰的女子侧身坐于暗色车厢内，双手向两侧拉开厚重的蓝色窗帘，露出红色的车厢门框边缘。","analysis":"画面采用中心构图，人物位于画面中央，呈坐姿，上半身及大腿部分清晰可见。背景为深黑色的车厢内部，与人物深蓝色衣物形成低对比度，而白色的领口与袖口在暗调中形成高光点。两侧垂下的蓝色窗帘与红色门框形成鲜明的色彩对比，光线柔和地照亮人物面部与衣饰，营造出一种静谧且略带压抑的视觉氛围。","prompt":"低分辨率的复古风格画面，一名深色头发的女子侧身坐于暗色空间内，身穿深蓝色长袖连衣裙，领口与袖口装饰着繁复的白色蕾丝。她双手向两侧拉开厚重的深蓝色窗帘，露出红色的木质门框。背景是深邃的黑色，光线集中在人物面部与白色衣饰上，形成强烈的明暗对比。画面色彩以深蓝、黑、红、白为主，质感略显粗糙，呈现出一种旧时代的静谧感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T02:00:05+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/06 (45).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.441,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-36774772f568c874","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-c8660c22a55b1c81","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/18 (45).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"昏暗室内，左侧金发男子身着紫红上衣，双手捧持一灰褐色团状物，右侧女子身着白衣，两人相对而立，背景为深色墙面与红色边框结构。","analysis":"画面采用近景构图，人物上半身占据主要视野。左侧男子身形较大，处于前景，右侧女子身形较小，位于稍后位置。光线柔和，主要照亮人物面部与衣物，背景深暗，形成强烈明暗对比。紫红色与白色衣物在深色背景下显得突出，红色边框作为视觉分割线。","prompt":"昏暗室内场景，左侧一名金发男子，身穿紫红色长袖上衣，双手在胸前捧着一个灰褐色团状物体，低头注视。右侧一名长发女子，身穿白色高领上衣，侧脸微笑，目光投向男子手中的物体。背景是深黑色的粗糙墙面，中间有一个醒目的红色拱形边框结构，将两人分隔在左右两侧。光线柔和地打在人物面部和衣物上，与深色背景形成对比，画面色调偏暖，具有复古质感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T02:00:13+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/18 (45).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.499,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-01cf51d35d445628","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-9672da058cd3556b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/30 (45).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"一座简易茅草棚屋正在猛烈燃烧，火焰吞噬了屋顶和左侧墙体，浓烟升腾，右侧竖立着一根粗糙的木桩，地面散落着碎木。","analysis":"画面主体为燃烧的棚屋，占据画面中心及左侧大部分区域。右侧前景有一根垂直的深色木桩，形成视觉框架。棚屋结构由木柱支撑，茅草屋顶已完全着火，呈现明亮的橙黄色。左侧火焰最为剧烈，形成巨大的火团。背景天空被烟雾染成灰黄色，光线主要来自火光，整体色调偏暖，明暗对比强烈，展现了火灾的混乱与破坏力。","prompt":"低分辨率画面，一座简易的茅草棚屋正在燃烧。棚屋由几根细木柱支撑，屋顶覆盖着茅草，此刻已被大火吞噬，火焰呈明亮的橙黄色，从屋顶和左侧墙体猛烈窜出，形成巨大的火团。浓烟向上升腾，将背景天空染成灰黄色。画面右侧前景竖立着一根粗糙的深色木桩，略微倾斜。地面是干燥的泥土，散落着一些碎木和杂物。整体光线昏暗，主要光源来自火光，营造出一种紧张、混乱的火灾现场氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T02:00:21+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/30 (45).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.513,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-aa2db6b7d29b1ea3","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-1c2fc00f5c1a5700","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/42 (44).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"一名戴金属头盔、蓄浓密胡须的男子侧身面向右侧，右手握持一根竖直木杆。背景为宽阔平静的河流，两岸分布着茂密的绿色树林，天空呈现灰白色。","analysis":"画面采用侧面视角，人物占据左侧约三分之一区域，右侧大面积留白给河流与远景。人物头部及肩部清晰可见，金属头盔表面有磨损痕迹，胡须浓密。光线柔和均匀，无明显阴影，色彩以土黄、灰绿和淡蓝为主，整体色调偏冷且饱和度较低。","prompt":"低分辨率写实风格画面，一名蓄着浓密深色络腮胡的男子侧身面向右侧，头戴表面斑驳磨损的圆顶金属头盔，身穿土黄色上衣，肩部可见皮质背带。男子右手握持一根竖直的粗糙木杆，木杆贯穿画面右侧。背景是宽阔平静的灰蓝色河流，远处两岸延伸着茂密的深绿色树林，天空为灰白色。光线柔和漫射，无强烈阴影，整体色调偏冷，呈现低饱和度的土黄与灰绿对比，人物轮廓清晰但细节模糊。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T02:00:28+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/42 (44).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.509,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-9078dff29dd71832","origin":"visual"},{"work_id":"src-511fd3a9e5b4cd1b","frame_id":"FG-2a5e9f5c5367abcc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/54 (40).jpg","source_page":"https://film-grab.com/2010/11/20/aguirre-the-wrath-of-god-aguirre-der-zorn-gottes/","scene":"画面主体为一名金发人物的面部与头部，左侧被带有铆钉的深色金属物体大面积遮挡，背景昏暗，仅见局部轮廓。","analysis":"构图极度紧凑，人物面部占据画面右侧约三分之二区域，左侧金属物体占据约三分之一。人物头部微仰，视线向上，金发凌乱地垂落在脸侧。光线从上方或侧方打在面部，形成柔和的明暗过渡，金属物体表面有微弱反光。整体色调偏暖，背景深暗，突出了人物面部的轮廓与发丝细节。","prompt":"低分辨率画面，主体为一名金发人物的面部特写，头部微仰，视线向上。人物面部占据画面右侧，金发凌乱，部分发丝垂在脸前。画面左侧被一个巨大的深色金属物体遮挡，该物体表面有铆钉细节，呈弧形结构。背景深暗模糊，光线柔和地照亮人物面部，形成暖色调的明暗对比。整体构图紧凑，强调人物与左侧金属物体的空间关系，无多余背景细节。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T02:00:35+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/54 (40).jpg","observed_dimensions":[746,572],"source_thumbnail_dimensions":[500,383],"source_image_match_mae":0.497,"observed_resolution":"low","observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"id":"VP-aa856dc4051dc671","origin":"visual"}]};